import { useCEProductCustomization } from '../../bitf-customization-engine/useCEProductCustomization';
import { useTranslate } from '../../hooks/useTranslate';

export default function CEProductCustomizationPrice({
  storeName = 'shared',
  language = 'it',
  locale,
  showOnlyPrice = false,
  extraTextClassName = '',
  extraPriceClassName = '',
  extraCompareAtPriceClassName = '',
  currencyCode,
  selectVariantPrice,
}) {
  const resolvedLanguage = language || locale;
  const { translate } = useTranslate(resolvedLanguage);
  const { store } = useCEProductCustomization({ storeName, watchStoreChanges: false });
  const price = store?.price;
  const compareAtPrice = store?.compareAtPrice;
  const resolvedCurrencyCode = currencyCode || store?.currencyCode;

  function formatCurrency(number) {
    if (typeof number !== 'number' || !resolvedCurrencyCode) return number;
    try {
      return new Intl.NumberFormat(resolvedLanguage, { style: 'currency', currency: resolvedCurrencyCode }).format(
        number,
      );
    } catch (e) {
      return number + ' ' + resolvedCurrencyCode;
    }
  }

  return store.isLoadingCustomization === false ? (
    <>
      {showOnlyPrice ? (
        <>
          {compareAtPrice && compareAtPrice > price ? (
            <div className={`${extraCompareAtPriceClassName} compare-at-price-customization`}>
              {formatCurrency(compareAtPrice)}
            </div>
          ) : null}
          <div className={`${extraPriceClassName} price-customization`}>
            {price ? formatCurrency(price) : translate('customization.form.free')}
          </div>
        </>
      ) : (
        <div className="product-customization-price gap-1">
          <span className={`product-customization-price__label Small Medium ${extraTextClassName}`}>
            {translate('customization.price.total')}
          </span>
          <span className={`product-customization-price__value Small Medium ${extraPriceClassName}`}>
            {price ? formatCurrency(price) : translate('customization.form.free')}
          </span>
        </div>
      )}
    </>
  ) : (
    <>
      {showOnlyPrice ? (
        <>
          {compareAtPrice && compareAtPrice > price ? (
            <div className={`${extraCompareAtPriceClassName} compare-at-price-customization`}>
              {formatCurrency(compareAtPrice)}
            </div>
          ) : null}

          <div className="Headline-5 price-customization">
            {selectVariantPrice ? formatCurrency(selectVariantPrice) : translate('customization.form.free')}
          </div>
        </>
      ) : (
        <div className="product-customization-price gap-1">
          <span className={`product-customization-price__label Small Medium ${extraTextClassName}`}>
            {translate('customization.price.total')}
          </span>
          <span className={`product-customization-price__value Small Medium ${extraPriceClassName}`}>
            {selectVariantPrice ? formatCurrency(selectVariantPrice) : translate('customization.form.free')}
          </span>
        </div>
      )}
    </>
  );
}
